/** Guarded exact-byte source Apply, rollback, and crash recovery. It never invokes Git mutation commands. */
public final class MigrationApplyService {
    interface Faults extends MigrationSourceTransactionWriter.Faults {
        default void beforeArtifact(String kind,String logicalRef)throws IOException{}
        default void beforeJournal(MigrationApplyTransaction.EventType type,long sequence)throws IOException{}
        default void beforePostApplyCheckpoint()throws IOException{}
        Faults NONE=new Faults(){};
    }
    private final MigrationGitService git;private final MigrationDecisionResolver decisions=new MigrationDecisionResolver();
    private final MigrationApplyCodec codec=new MigrationApplyCodec();private final Faults faults;private final MigrationSourceTransactionWriter writer;
    public MigrationApplyService(){this(new MigrationGitService(),Faults.NONE);}
    MigrationApplyService(MigrationGitService git,Faults faults){this.git=git;this.faults=faults==null?Faults.NONE:faults;this.writer=new MigrationSourceTransactionWriter(this.faults);}

    public PreparationResult prepare(PreparationInput input)throws IOException{
        Objects.requireNonNull(input);try{return prepareChecked(input);}catch(PrepareFailure f){return new PreparationResult(f.status,null,List.copyOf(f.issues));}catch(IOException e){return new PreparationResult(PreparationStatus.ARTIFACT_INTEGRITY_FAILED,null,List.of(e.getClass().getSimpleName()));}
    }
    private PreparationResult prepareChecked(PreparationInput in)throws IOException{
        List<String>selected=in.selectedProposalIds()==null?List.of():in.selectedProposalIds().stream().distinct().sorted().toList();
        if(selected.isEmpty()||selected.size()>MigrationApplyPlan.MAX_PROPOSALS)throw fail(PreparationStatus.APPLY_LIMIT_EXCEEDED,"selected proposal bound");
        MigrationGitService.Result inspected=git.inspect(in.projectRoot());if(inspected.localContext()==null)throw fail(PreparationStatus.STALE_PRECONDITION,"repository unavailable");
        if(inspected.preflight().completeness()!=MigrationGitPreflight.Completeness.COMPLETE||inspected.sourceState().completeness()!=MigrationSourceStateFingerprint.Completeness.COMPLETE)throw fail(PreparationStatus.STALE_PRECONDITION,"fresh source state incomplete");
        MigrationCheckpoint proposalCheckpoint=in.proposalCheckpoint();if(!in.proposalSet().checkpointRef().equals(proposalCheckpoint.checkpointId()))throw fail(PreparationStatus.STALE_PRECONDITION,"proposal checkpoint mismatch");
        if(!proposalCheckpoint.repositoryBindingRef().equals(inspected.preflight().repositoryBindingRef())||!proposalCheckpoint.worktreeBindingRef().equals(inspected.preflight().worktreeBindingRef()))throw fail(PreparationStatus.STALE_PRECONDITION,"repository/worktree binding changed");
        if(!proposalCheckpoint.head().equals(new MigrationCheckpoint.Head(inspected.preflight().head().state(),inspected.preflight().head().commit(),inspected.preflight().head().tree(),inspected.preflight().head().branch())))throw fail(PreparationStatus.STALE_PRECONDITION,"HEAD/branch changed");
        if(!inspected.preflight().ongoingOperations().isEmpty()||!inspected.preflight().conflicted().isEmpty())throw fail(PreparationStatus.STALE_PRECONDITION,"incompatible Git operation");
        MigrationCheckpoint fresh=MigrationCheckpoint.create(inspected.preflight(),inspected.sourceState(),proposalCheckpoint.configuration(),proposalCheckpoint.artifacts(),in.proposalSet().proposalSetId(),in.decisionLedger().ledgerSemanticDigest());in.store().write(fresh);
        Map<String,MigrationProposal>all=new HashMap<>();in.proposalSet().proposals().forEach(p->all.put(p.proposalId(),p));List<MigrationProposal>proposals=new ArrayList<>();for(String id:selected){MigrationProposal p=all.get(id);if(p==null)throw fail(PreparationStatus.PROPOSAL_NOT_FOUND,id);if(p.eligibility()!=MigrationProposal.Eligibility.READY_FOR_REVIEW)throw fail(PreparationStatus.NOT_APPLYABLE_SOURCE_PROPOSAL,id+":"+p.eligibility());if(p.sourceEdits().isEmpty())throw fail(PreparationStatus.NO_SOURCE_CHANGE,id);proposals.add(p);}
        for(var conflict:in.proposalSet().conflicts())if(conflict.proposalIds().stream().anyMatch(selected::contains))throw fail(PreparationStatus.CONFLICTING_PROPOSAL,conflict.code());for(MigrationProposal p:proposals)if(!p.conflicts().isEmpty())throw fail(PreparationStatus.CONFLICTING_PROPOSAL,p.proposalId());
        List<String>decisionRefs=new ArrayList<>(),evidenceDigests=new ArrayList<>();Map<String,MigrationEvidenceRef>currentEvidence=new HashMap<>();for(var e:in.currentEvidence())currentEvidence.put(e.logicalArtifactRef(),e);
        for(MigrationProposal p:proposals){List<MigrationEvidenceRef>exact=new ArrayList<>();for(var expected:p.evidenceRefs()){var actual=currentEvidence.get(expected.logicalArtifactRef());if(!expected.equals(actual))throw fail(PreparationStatus.DECISION_INVALID,"evidence changed:"+expected.logicalArtifactRef());exact.add(actual);evidenceDigests.add(actual.canonicalDigest());}var resolved=decisions.resolve(in.decisionLedger(),p,proposalCheckpoint.checkpointId(),exact);if(resolved.status()!=MigrationDecisionResolver.Status.APPROVED)throw fail(resolved.status()==MigrationDecisionResolver.Status.DECISION_AMBIGUOUS?PreparationStatus.DECISION_AMBIGUOUS:PreparationStatus.DECISION_INVALID,resolved.issues().toArray(String[]::new));decisionRefs.add(resolved.effectiveDecision().decisionRef());}
        currentEvidence.values().stream().map(MigrationEvidenceRef::canonicalDigest).forEach(evidenceDigests::add);
        List<String>resolutionRefs=resolveDependencies(in.proposalSet(),selected,in.dependencyResolutions(),proposalCheckpoint.checkpointId(),evidenceDigests);
        Map<String,List<EditBinding>>byFile=new TreeMap<>();for(MigrationProposal p:proposals){if(p.sourceEdits().size()!=p.sourcePreconditions().size())throw fail(PreparationStatus.STALE_PRECONDITION,"edit/precondition cardinality");for(MigrationSourceEdit edit:p.sourceEdits()){MigrationSourcePrecondition pre=p.sourcePreconditions().stream().filter(x->x.logicalPath().equals(edit.logicalPath())&&x.exactCharacterRange().startUtf16()==edit.startUtf16()&&x.exactCharacterRange().endUtf16Exclusive()==edit.endUtf16Exclusive()).findFirst().orElseThrow(()->fail(PreparationStatus.STALE_PRECONDITION,"edit has no exact precondition"));byFile.computeIfAbsent(edit.logicalPath(),x->new ArrayList<>()).add(new EditBinding(p,pre,edit));}}
        if(byFile.size()>MigrationApplyPlan.MAX_FILES||byFile.values().stream().mapToInt(List::size).sum()>MigrationApplyPlan.MAX_EDITS)throw fail(PreparationStatus.APPLY_LIMIT_EXCEEDED,"file/edit bound");
        List<MigrationApplyPlan.FilePlan>files=new ArrayList<>();long originals=0,targets=0;StringBuilder diff=new StringBuilder();Path root=inspected.localContext().worktreeRoot().toRealPath();
        for(var entry:byFile.entrySet()){BuiltFile built=build(root,entry.getKey(),entry.getValue(),proposalCheckpoint);originals+=built.original().length;targets+=built.proposed().length;if(originals>MigrationApplyPlan.MAX_AGGREGATE_BYTES||targets>MigrationApplyPlan.MAX_AGGREGATE_BYTES)throw fail(PreparationStatus.APPLY_LIMIT_EXCEEDED,"aggregate bytes");String originalRef=sourceRef("backups",built.originalDigest()),targetRef=sourceRef("targets",built.proposedDigest());persist(in.store(),originalRef,built.original(),"backup");persist(in.store(),targetRef,built.proposed(),"target");files.add(new MigrationApplyPlan.FilePlan(entry.getKey(),built.originalDigest(),built.proposedDigest(),new MigrationApplyPlan.SourceArtifact(originalRef,built.originalDigest(),built.original().length),new MigrationApplyPlan.SourceArtifact(targetRef,built.proposedDigest(),built.proposed().length),built.ranges(),built.preconditionDigests(),built.proposalIds(),built.metadata(),!built.originalDigest().equals(built.proposedDigest())));diff.append(exactDiff(entry.getKey(),built.original(),built.proposed()));if(diff.toString().getBytes(StandardCharsets.UTF_8).length>MigrationApplyPlan.MAX_DIFF_BYTES)throw fail(PreparationStatus.APPLY_LIMIT_EXCEEDED,"final diff bound");}
        byte[] diffBytes=diff.toString().getBytes(StandardCharsets.UTF_8);String diffDigest=MigrationSourceTransactionWriter.sha(diffBytes);
        String provisionalDiffRef="apply/diffs/content-"+diffDigest.substring("sha256:".length())+".patch";
        String verification=verificationDigest(proposals);MigrationApplyPlan plan=MigrationApplyPlan.create(inspected.preflight().repositoryBindingRef(),inspected.preflight().worktreeBindingRef(),in.proposalSet().proposalSetId(),selected,in.decisionLedger().ledgerSemanticDigest(),decisionRefs,resolutionRefs,evidenceDigests,proposalCheckpoint.checkpointId(),fresh.checkpointId(),files,verification,originals,targets,provisionalDiffRef,diffDigest,diffBytes.length,MigrationApplyPlan.MAX_DIFF_BYTES,List.of("VERIFICATION_PENDING_AFTER_APPLY"));String planRef=planRef(plan.applyPlanId());persist(in.store(),planRef,codec.write(plan),"plan");MigrationApplyPlan loaded=codec.readPlan(read(in.store(),planRef,MigrationApplyCodec.MAX_BYTES));if(!loaded.equals(plan))throw fail(PreparationStatus.ARTIFACT_INTEGRITY_FAILED,"plan roundtrip");persist(in.store(),plan.finalDiffRef(),diffBytes,"diff");return new PreparationResult(PreparationStatus.PREPARED,plan,List.of());
    }

    public MigrationApplyResult apply(MigrationApplyPlan supplied,Path projectRoot,MigrationStateStore store,
            MigrationTargetedAuthorization applyAuthorization,MigrationTargetedAuthorization compensationAuthorization)throws IOException{
        String tx=MigrationApplyTransaction.id(supplied);String before=supplied.preparationCheckpointRef();
        if(applyAuthorization==null||!applyAuthorization.allows(MigrationTargetedAuthorization.Capability.APPLY_APPROVED_SOURCE_CHANGES)||!applyAuthorization.targets(supplied.applyPlanId(),supplied.repositoryBindingRef(),supplied.worktreeBindingRef()))return result(supplied,tx,MigrationApplyResult.Status.APPROVAL_REQUIRED,List.of(),before,null,false,null,null,List.of("APPROVAL_REQUIRED"));
        MigrationApplyPlan plan;try{plan=codec.readPlan(read(store,planRef(supplied.applyPlanId()),MigrationApplyCodec.MAX_BYTES));}catch(Exception e){return result(supplied,tx,MigrationApplyResult.Status.RECOVERY_REQUIRED,List.of(),before,null,false,null,null,List.of("APPLY_PLAN_ARTIFACT_INVALID"));}if(!plan.equals(supplied))return result(supplied,tx,MigrationApplyResult.Status.APPROVAL_REQUIRED,List.of(),before,null,false,null,null,List.of("AUTHORIZED_PLAN_CHANGED"));
        try(ApplyLock lock=lock(store,plan.repositoryBindingRef())){if(lock==null)return result(plan,tx,MigrationApplyResult.Status.APPLY_LOCK_UNAVAILABLE,List.of(),before,null,false,null,null,List.of("APPLY_LOCK_UNAVAILABLE"));return applyLocked(plan,tx,projectRoot,store,compensationAuthorization);}
    }
    private MigrationApplyResult applyLocked(MigrationApplyPlan plan,String tx,Path projectRoot,MigrationStateStore store,MigrationTargetedAuthorization compensation)throws IOException{
        MigrationGitService.Result state=git.inspect(projectRoot);if(!binding(state,plan)||!state.preflight().ongoingOperations().isEmpty())return result(plan,tx,MigrationApplyResult.Status.STALE_PRECONDITION,List.of(),plan.preparationCheckpointRef(),null,false,null,List.of("LAST_MOMENT_REPOSITORY_STATE_CHANGED"));Path root=state.localContext().worktreeRoot().toRealPath();List<MigrationApplyResult.FileResult>initial=new ArrayList<>();boolean allProposed=true,allOriginal=true;for(var file:plan.filePlans()){String observed=digestTarget(root,file.logicalPath());allProposed&=file.proposedSha256().equals(observed);allOriginal&=file.originalSha256().equals(observed);initial.add(new MigrationApplyResult.FileResult(file.logicalPath(),file.proposedSha256().equals(observed)?MigrationApplyResult.FileStatus.ALREADY_APPLIED:file.originalSha256().equals(observed)?MigrationApplyResult.FileStatus.NOT_ATTEMPTED:MigrationApplyResult.FileStatus.STALE_PRECONDITION,observed,List.of()));}if(allProposed)return result(plan,tx,MigrationApplyResult.Status.ALREADY_APPLIED,initial,plan.preparationCheckpointRef(),null,true,plan.finalDiffRef(),List.of());if(!allOriginal)return result(plan,tx,MigrationApplyResult.Status.STALE_PRECONDITION,initial,plan.preparationCheckpointRef(),null,false,null,List.of("BATCH_LAST_MOMENT_VALIDATION_FAILED"));
        Journal journal;try{for(var file:plan.filePlans()){verifyArtifact(store,file.originalArtifact());verifyArtifact(store,file.proposedArtifact());}verifyDiffArtifact(store,plan);MigrationApplyTransaction.OwnershipRegistry registry=registry(tx,plan);String registryRef=registryRef(tx);persist(store,registryRef,codec.write(registry),"registry");journal=new Journal(store,tx,codec,faults);if(!journal.events().isEmpty())return result(plan,tx,MigrationApplyResult.Status.RECOVERY_REQUIRED,initial,plan.preparationCheckpointRef(),null,true,plan.finalDiffRef(),journal.head(),List.of("EXISTING_TRANSACTION_REQUIRES_RECOVERY"));journal.add(MigrationApplyTransaction.EventType.PREPARED,null,null,null);journal.add(MigrationApplyTransaction.EventType.WRITING,null,null,null);}catch(IOException|RuntimeException e){return result(plan,tx,MigrationApplyResult.Status.ABORTED,initial,plan.preparationCheckpointRef(),null,false,null,List.of("PRE_WRITE_PREPARATION_FAILED:"+e.getClass().getSimpleName()));}
        List<MigrationApplyResult.FileResult>written=new ArrayList<>();int index=0;String failure=null;MigrationApplyResult.Status failureStatus=MigrationApplyResult.Status.WRITE_FAILED;for(var file:plan.filePlans()){String observed=digestTarget(root,file.logicalPath());if(!file.originalSha256().equals(observed)){failure="SOURCE_CHANGED_DURING_TRANSACTION";failureStatus=written.stream().anyMatch(x->x.status()==MigrationApplyResult.FileStatus.APPLIED)?MigrationApplyResult.Status.PARTIAL_APPLY:MigrationApplyResult.Status.STALE_PRECONDITION;break;}if(!file.writeRequired()){written.add(new MigrationApplyResult.FileResult(file.logicalPath(),MigrationApplyResult.FileStatus.ALREADY_APPLIED,observed,List.of()));continue;}journal.add(MigrationApplyTransaction.EventType.REPLACE_STARTED,file.logicalPath(),observed,null);byte[]target=read(store,file.proposedArtifact().logicalRef(),MigrationApplyPlan.MAX_FILE_BYTES);MigrationSourceTransactionWriter.WriteResult wr;try{wr=writer.replace(source(root,file.logicalPath()),target,tx,file.originalSha256(),index,file.metadata());}catch(IOException e){failure="WRITE_FAILED:"+e.getClass().getSimpleName();failureStatus=MigrationApplyResult.Status.PARTIAL_APPLY;String after=digestTarget(root,file.logicalPath());wr=new MigrationSourceTransactionWriter.WriteResult(file.proposedSha256().equals(after),after,failure);}if(!wr.written()){failure=wr.issue();boolean priorApplied=written.stream().anyMatch(x->x.status()==MigrationApplyResult.FileStatus.APPLIED);failureStatus="VERIFY_DIGEST_FAILED".equals(wr.issue())?MigrationApplyResult.Status.VERIFY_DIGEST_FAILED:priorApplied?MigrationApplyResult.Status.PARTIAL_APPLY:MigrationApplyResult.Status.WRITE_FAILED;written.add(new MigrationApplyResult.FileResult(file.logicalPath(),"VERIFY_DIGEST_FAILED".equals(wr.issue())?MigrationApplyResult.FileStatus.VERIFY_DIGEST_FAILED:MigrationApplyResult.FileStatus.WRITE_FAILED,wr.observedDigest(),List.of(wr.issue())));break;}journal.add(MigrationApplyTransaction.EventType.FILE_REPLACED,file.logicalPath(),wr.observedDigest(),failure);written.add(new MigrationApplyResult.FileResult(file.logicalPath(),MigrationApplyResult.FileStatus.APPLIED,wr.observedDigest(),failure==null?List.of():List.of(failure)));index++;if(failure!=null)break;}
        if(failure!=null){journal.add(MigrationApplyTransaction.EventType.PARTIAL_APPLY,null,null,failure);for(int i=written.size();i<plan.filePlans().size();i++){var f=plan.filePlans().get(i);written.add(new MigrationApplyResult.FileResult(f.logicalPath(),MigrationApplyResult.FileStatus.NOT_ATTEMPTED,digestTarget(root,f.logicalPath()),List.of()));}boolean canCompensate=compensation!=null&&compensation.allows(MigrationTargetedAuthorization.Capability.ROLLBACK_TOOL_CHANGES)&&compensation.targets(plan.applyPlanId(),plan.repositoryBindingRef(),plan.worktreeBindingRef());if(canCompensate)return compensate(plan,tx,root,store,journal,written);return result(plan,tx,failureStatus,written,plan.preparationCheckpointRef(),null,true,plan.finalDiffRef(),journal.head(),List.of(failure));}
        journal.add(MigrationApplyTransaction.EventType.APPLY_COMPLETED,null,null,null);String post=null;try{faults.beforePostApplyCheckpoint();MigrationGitService.Result fresh=git.inspect(root);MigrationCheckpoint prior=readCheckpoint(store,plan.preparationCheckpointRef());MigrationCheckpoint checkpoint=MigrationCheckpoint.create(fresh.preflight(),fresh.sourceState(),prior.configuration(),prior.artifacts(),prior.proposalSetRef(),prior.decisionsRef());store.write(checkpoint);post=checkpoint.checkpointId();journal.add(MigrationApplyTransaction.EventType.VERIFICATION_PENDING,null,null,null);}catch(Exception e){journal.add(MigrationApplyTransaction.EventType.RECOVERY_REQUIRED,null,null,"POST_APPLY_STATE_RECORDING_FAILED");return result(plan,tx,MigrationApplyResult.Status.RECOVERY_REQUIRED,written,plan.preparationCheckpointRef(),post,true,plan.finalDiffRef(),journal.head(),List.of("POST_APPLY_STATE_RECORDING_FAILED"));}return result(plan,tx,MigrationApplyResult.Status.APPLIED,written,plan.preparationCheckpointRef(),post,true,plan.finalDiffRef(),journal.head(),List.of("VERIFICATION_PENDING"));
    }

    private MigrationApplyResult compensate(MigrationApplyPlan plan,String tx,Path root,MigrationStateStore store,Journal journal,List<MigrationApplyResult.FileResult>results)throws IOException{journal.add(MigrationApplyTransaction.EventType.COMPENSATION_STARTED,null,null,null);boolean blocked=false;List<MigrationApplyResult.FileResult>out=new ArrayList<>();for(var result:results){var file=plan.filePlans().stream().filter(x->x.logicalPath().equals(result.logicalPath())).findFirst().orElseThrow();if(result.status()!=MigrationApplyResult.FileStatus.APPLIED){out.add(result);continue;}String current=digestTarget(root,file.logicalPath());if(!file.proposedSha256().equals(current)){blocked=true;out.add(new MigrationApplyResult.FileResult(file.logicalPath(),MigrationApplyResult.FileStatus.COMPENSATION_BLOCKED,current,List.of("USER_MODIFIED")));continue;}byte[]original=read(store,file.originalArtifact().logicalRef(),MigrationApplyPlan.MAX_FILE_BYTES);var wr=writer.replace(source(root,file.logicalPath()),original,tx,file.proposedSha256(),0,file.metadata());if(wr.written()){journal.add(MigrationApplyTransaction.EventType.FILE_COMPENSATED,file.logicalPath(),wr.observedDigest(),null);out.add(new MigrationApplyResult.FileResult(file.logicalPath(),MigrationApplyResult.FileStatus.COMPENSATED,wr.observedDigest(),List.of()));}else{blocked=true;out.add(new MigrationApplyResult.FileResult(file.logicalPath(),MigrationApplyResult.FileStatus.COMPENSATION_BLOCKED,wr.observedDigest(),List.of(wr.issue())));}}journal.add(MigrationApplyTransaction.EventType.COMPENSATION_COMPLETED,null,null,blocked?"PARTIAL":null);return result(plan,tx,blocked?MigrationApplyResult.Status.PARTIAL_COMPENSATION:MigrationApplyResult.Status.COMPENSATED,out,plan.preparationCheckpointRef(),null,!blocked,plan.finalDiffRef(),journal.head(),blocked?List.of("COMPENSATION_PARTIALLY_BLOCKED"):List.of());}

    public MigrationRollbackResult rollback(String transactionId,Path projectRoot,MigrationStateStore store,MigrationTargetedAuthorization authorization)throws IOException{
        try(MigrationTransactionOperationLock operationLock=MigrationTransactionOperationLock.tryAcquire(store,transactionId)){
            if(operationLock==null)return new MigrationRollbackResult(transactionId,MigrationRollbackResult.Status.ROLLBACK_BLOCKED,List.of(),null,List.of("VERIFICATION_TRANSACTION_BUSY"));
            return rollbackLocked(transactionId,projectRoot,store,authorization);
        }
    }

    private MigrationRollbackResult rollbackLocked(String transactionId,Path projectRoot,MigrationStateStore store,MigrationTargetedAuthorization authorization)throws IOException{MigrationApplyTransaction.OwnershipRegistry registry;try{registry=codec.readRegistry(read(store,registryRef(transactionId),MigrationApplyCodec.MAX_BYTES));}catch(Exception e){return new MigrationRollbackResult(transactionId,MigrationRollbackResult.Status.RECOVERY_REQUIRED,List.of(),null,List.of("OWNERSHIP_REGISTRY_INVALID"));}MigrationApplyPlan plan=codec.readPlan(read(store,planRef(registry.applyPlanId()),MigrationApplyCodec.MAX_BYTES));if(!transactionArtifactsMatch(transactionId,registry,plan))return new MigrationRollbackResult(transactionId,MigrationRollbackResult.Status.RECOVERY_REQUIRED,List.of(),null,List.of("TRANSACTION_ARTIFACT_MISMATCH"));if(authorization==null||!authorization.allows(MigrationTargetedAuthorization.Capability.ROLLBACK_TOOL_CHANGES)||!authorization.targets(transactionId,plan.repositoryBindingRef(),plan.worktreeBindingRef()))return new MigrationRollbackResult(transactionId,MigrationRollbackResult.Status.APPROVAL_REQUIRED,List.of(),null,List.of("APPROVAL_REQUIRED"));try(ApplyLock lock=lock(store,plan.repositoryBindingRef())){if(lock==null)return new MigrationRollbackResult(transactionId,MigrationRollbackResult.Status.ROLLBACK_BLOCKED,List.of(),null,List.of("APPLY_LOCK_UNAVAILABLE"));Path root=git.inspect(projectRoot).localContext().worktreeRoot().toRealPath();Journal journal=new Journal(store,transactionId,codec,faults);journal.add(MigrationApplyTransaction.EventType.ROLLBACK_STARTED,null,null,null);List<MigrationRollbackResult.FileResult>out=new ArrayList<>();boolean blocked=false,failed=false,restored=false;int index=0;for(var file:plan.filePlans()){Path target=source(root,file.logicalPath());if(!Files.exists(target,LinkOption.NOFOLLOW_LINKS)){blocked=true;out.add(new MigrationRollbackResult.FileResult(file.logicalPath(),MigrationRollbackResult.FileStatus.MISSING,List.of()));continue;}String current=digestTarget(root,file.logicalPath());if(file.originalSha256().equals(current)){out.add(new MigrationRollbackResult.FileResult(file.logicalPath(),MigrationRollbackResult.FileStatus.ALREADY_ORIGINAL,List.of()));continue;}if(!file.proposedSha256().equals(current)){blocked=true;out.add(new MigrationRollbackResult.FileResult(file.logicalPath(),MigrationRollbackResult.FileStatus.USER_MODIFIED,List.of()));continue;}try{verifyArtifact(store,file.originalArtifact());byte[]original=read(store,file.originalArtifact().logicalRef(),MigrationApplyPlan.MAX_FILE_BYTES);var wr=writer.replace(target,original,transactionId,file.proposedSha256(),index++,file.metadata());if(wr.written()){restored=true;journal.add(MigrationApplyTransaction.EventType.FILE_ROLLED_BACK,file.logicalPath(),wr.observedDigest(),null);out.add(new MigrationRollbackResult.FileResult(file.logicalPath(),MigrationRollbackResult.FileStatus.RESTORED,List.of()));}else{failed=true;out.add(new MigrationRollbackResult.FileResult(file.logicalPath(),MigrationRollbackResult.FileStatus.WRITE_FAILED,List.of(wr.issue())));}}catch(IOException e){failed=true;out.add(new MigrationRollbackResult.FileResult(file.logicalPath(),MigrationRollbackResult.FileStatus.WRITE_FAILED,List.of(e.getClass().getSimpleName())));}}MigrationRollbackResult.Status status=failed?MigrationRollbackResult.Status.RECOVERY_REQUIRED:blocked?(restored?MigrationRollbackResult.Status.PARTIAL_ROLLBACK:MigrationRollbackResult.Status.ROLLBACK_BLOCKED):MigrationRollbackResult.Status.ROLLED_BACK;journal.add(status==MigrationRollbackResult.Status.ROLLED_BACK?MigrationApplyTransaction.EventType.ROLLBACK_COMPLETED:MigrationApplyTransaction.EventType.RECOVERY_REQUIRED,null,null,status.name());return new MigrationRollbackResult(transactionId,status,out,journal.head(),List.of());}}

    public MigrationRecoveryPlan inspectRecovery(String transactionId,Path projectRoot,MigrationStateStore store)throws IOException{MigrationApplyTransaction.OwnershipRegistry registry;try{registry=codec.readRegistry(read(store,registryRef(transactionId),MigrationApplyCodec.MAX_BYTES));}catch(Exception e){return new MigrationRecoveryPlan(transactionId,MigrationRecoveryPlan.Situation.RECOVERY_REQUIRED,List.of(),null,List.of("MISSING_OR_CORRUPT_OWNERSHIP"));}MigrationApplyPlan plan;try{plan=codec.readPlan(read(store,planRef(registry.applyPlanId()),MigrationApplyCodec.MAX_BYTES));if(!transactionArtifactsMatch(transactionId,registry,plan))throw new IOException("transaction mismatch");for(var file:plan.filePlans())verifyArtifact(store,file.originalArtifact());}catch(Exception e){return new MigrationRecoveryPlan(transactionId,MigrationRecoveryPlan.Situation.RECOVERY_REQUIRED,List.of(),null,List.of("MISSING_OR_CORRUPT_BACKUP_OR_PLAN"));}Journal journal;try{journal=new Journal(store,transactionId,codec,faults);journal.verify();}catch(Exception e){return new MigrationRecoveryPlan(transactionId,MigrationRecoveryPlan.Situation.RECOVERY_REQUIRED,List.of(),null,List.of("CORRUPT_JOURNAL_CHAIN"));}Path root=git.inspect(projectRoot).localContext().worktreeRoot().toRealPath();List<MigrationRecoveryPlan.FileState>states=new ArrayList<>();int original=0,applied=0,unknown=0,missing=0;for(var f:plan.filePlans()){Path p=source(root,f.logicalPath());if(!Files.exists(p,LinkOption.NOFOLLOW_LINKS)){missing++;states.add(new MigrationRecoveryPlan.FileState(f.logicalPath(),MigrationRecoveryPlan.TargetState.MISSING,null));continue;}String digest=digestTarget(root,f.logicalPath());if(f.originalSha256().equals(digest)){original++;states.add(new MigrationRecoveryPlan.FileState(f.logicalPath(),MigrationRecoveryPlan.TargetState.ORIGINAL,digest));}else if(f.proposedSha256().equals(digest)){applied++;states.add(new MigrationRecoveryPlan.FileState(f.logicalPath(),MigrationRecoveryPlan.TargetState.TOOL_APPLIED,digest));}else{unknown++;states.add(new MigrationRecoveryPlan.FileState(f.logicalPath(),MigrationRecoveryPlan.TargetState.UNKNOWN_MODIFIED,digest));}}MigrationRecoveryPlan.Situation situation;if(unknown>0||missing>0)situation=MigrationRecoveryPlan.Situation.ROLLBACK_PARTIALLY_BLOCKED;else if(applied==0)situation=MigrationRecoveryPlan.Situation.SAFE_TO_ABANDON;else if(original==0)situation=MigrationRecoveryPlan.Situation.ALL_APPLIED_NEEDS_RECONCILIATION;else situation=MigrationRecoveryPlan.Situation.GUARDED_ROLLBACK_AVAILABLE;return new MigrationRecoveryPlan(transactionId,situation,states,journal.head(),List.of());}

    /** Removes only digest-verified sibling temps named by this transaction's started replacements. */
    public TempCleanupResult cleanupOwnedTemps(String transactionId,Path projectRoot,MigrationStateStore store)throws IOException{
        var registry=codec.readRegistry(read(store,registryRef(transactionId),MigrationApplyCodec.MAX_BYTES));
        var plan=codec.readPlan(read(store,planRef(registry.applyPlanId()),MigrationApplyCodec.MAX_BYTES));
        var journal=new Journal(store,transactionId,codec,faults);Set<String>started=new HashSet<>();
        journal.events().stream().filter(e->e.type()==MigrationApplyTransaction.EventType.REPLACE_STARTED&&e.logicalPath()!=null).forEach(e->started.add(e.logicalPath()));
        Path root=git.inspect(projectRoot).localContext().worktreeRoot().toRealPath();List<String>removed=new ArrayList<>(),preserved=new ArrayList<>();
        for(var file:plan.filePlans()){if(!started.contains(file.logicalPath()))continue;Path target=source(root,file.logicalPath());Path temp=MigrationSourceTransactionWriter.ownedTemp(target,transactionId,file.proposedSha256());if(!Files.exists(temp,LinkOption.NOFOLLOW_LINKS))continue;if(Files.isSymbolicLink(temp)||!Files.isRegularFile(temp,LinkOption.NOFOLLOW_LINKS)||!file.proposedSha256().equals(MigrationSourceTransactionWriter.sha(Files.readAllBytes(temp)))){preserved.add(file.logicalPath());continue;}Files.delete(temp);removed.add(file.logicalPath());}
        return new TempCleanupResult(transactionId,removed.stream().sorted().toList(),preserved.stream().sorted().toList());
    }

    private List<String>resolveDependencies(MigrationProposalSet set,List<String>selected,List<MigrationDependencyResolution>resolutions,String checkpoint,List<String>evidence){List<String>refs=new ArrayList<>();for(var dep:set.dependencies()){if(!selected.contains(dep.fromProposalId()))continue;String semantic=dependencySemanticRef(dep);List<MigrationDependencyResolution>matches=resolutions.stream().filter(r->r.proposalId().equals(dep.fromProposalId())&&r.dependencyCode()==dep.code()&&r.dependencySemanticRef().equals(semantic)).toList();if(matches.size()!=1)throw fail(PreparationStatus.DEPENDENCY_UNSATISFIED,dep.fromProposalId()+":"+dep.code());var r=matches.get(0);if(!r.checkpointRef().equals(checkpoint)||!evidence.containsAll(r.evidenceDigests())||(dep.code()==MigrationProposalSet.DependencyCode.BLOCKED_BY_PROPOSAL&&(!Objects.equals(dep.toProposalId(),r.relatedProposalId())||!selected.contains(r.relatedProposalId()))))throw fail(PreparationStatus.DEPENDENCY_UNSATISFIED,"stale resolution:"+r.resolutionId());refs.add(r.resolutionId());}return refs.stream().distinct().sorted().toList();}
    public static String dependencySemanticRef(MigrationProposalSet.Dependency dep){return"migration-proposal-dependency-v1:sha256:"+MigrationDigests.digest("migration-proposal-dependency-v1",dep.fromProposalId(),dep.code().name(),dep.toProposalId()==null?"":dep.toProposalId());}
    private BuiltFile build(Path root,String logical,List<EditBinding>bindings,MigrationCheckpoint checkpoint)throws IOException{Path file=source(root,logical);if(Files.isSymbolicLink(file)||!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS))throw fail(PreparationStatus.STALE_PRECONDITION,"unsafe source path:"+logical);long size=Files.size(file);if(size>MigrationApplyPlan.MAX_FILE_BYTES)throw fail(PreparationStatus.APPLY_LIMIT_EXCEEDED,logical);byte[]original=Files.readAllBytes(file);String originalDigest=MigrationSourceTransactionWriter.sha(original);boolean bom=original.length>=3&&(original[0]&255)==0xef&&(original[1]&255)==0xbb&&(original[2]&255)==0xbf;String source=decode(original,bom?3:0);MigrationSourcePrecondition.Newline newline=newline(source);CompilationUnit unit=parse(source);List<MigrationSourceEdit>edits=new ArrayList<>();List<MigrationApplyPlan.ApprovedRange>ranges=new ArrayList<>();List<String>pres=new ArrayList<>(),proposals=new ArrayList<>();for(EditBinding b:bindings){var p=b.pre();var e=b.edit();if(!p.checkpointRef().equals(checkpoint.checkpointId())||!p.repositoryBindingRef().equals(checkpoint.repositoryBindingRef())||!p.worktreeBindingRef().equals(checkpoint.worktreeBindingRef())||!p.logicalPath().equals(logical)||!p.fileSha256().equals(originalDigest)||p.symlinkState()!=MigrationSourcePrecondition.SymlinkState.REGULAR_FILE||p.encoding()!=(bom?MigrationSourcePrecondition.Encoding.UTF8_BOM:MigrationSourcePrecondition.Encoding.UTF8)||p.newline()!=newline)throw fail(PreparationStatus.STALE_PRECONDITION,"source precondition:"+logical);if(!p.expectedNodeKind().equals("MethodCallExpr")||!p.constructIdentityDigest().matches("selector-source-construct-v1:sha256:[0-9a-f]{64}"))throw fail(PreparationStatus.STALE_PRECONDITION,"node/construct identity:"+logical);if(e.startUtf16()!=p.exactCharacterRange().startUtf16()||e.endUtf16Exclusive()!=p.exactCharacterRange().endUtf16Exclusive()||!e.originalConstructDigest().equals(p.originalConstructDigest())||!e.semanticBeforeRef().equals(p.currentSemanticDigest())||!e.semanticAfterRef().equals(p.proposedSemanticDigest()))throw fail(PreparationStatus.STALE_PRECONDITION,"edit/precondition mismatch:"+logical);if(e.endUtf16Exclusive()>source.length())throw fail(PreparationStatus.STALE_PRECONDITION,"range:"+logical);String construct=source.substring(e.startUtf16(),e.endUtf16Exclusive());String constructDigest="migration-source-construct-v1:sha256:"+MigrationDigests.digest("migration-source-construct-v1",construct);if(!constructDigest.equals(p.originalConstructDigest()))throw fail(PreparationStatus.STALE_PRECONDITION,"construct digest:"+logical);MethodCallExpr call=exactCall(unit,source,e.startUtf16(),e.endUtf16Exclusive());if(!semantic(call).equals(p.currentSemanticDigest()))throw fail(PreparationStatus.STALE_PRECONDITION,"semantic digest:"+logical);edits.add(e);ranges.add(new MigrationApplyPlan.ApprovedRange(e.startUtf16(),e.endUtf16Exclusive(),e.originalConstructDigest(),MigrationSourceTransactionWriter.sha(e.replacementText().getBytes(StandardCharsets.UTF_8)),e.semanticBeforeRef(),e.semanticAfterRef()));pres.add(MigrationApplyPlan.sourcePreconditionDigest(p));proposals.add(b.proposal().proposalId());}edits.sort(Comparator.comparingInt(MigrationSourceEdit::startUtf16));int end=-1;for(var e:edits){if(e.startUtf16()<end)throw fail(PreparationStatus.CONFLICTING_PROPOSAL,"overlap:"+logical);end=e.endUtf16Exclusive();}StringBuilder proposedText=new StringBuilder(source);for(var e:edits.stream().sorted(Comparator.comparingInt(MigrationSourceEdit::startUtf16).reversed()).toList())proposedText.replace(e.startUtf16(),e.endUtf16Exclusive(),e.replacementText());byte[]body=proposedText.toString().getBytes(StandardCharsets.UTF_8);byte[]proposed;if(bom){proposed=new byte[body.length+3];proposed[0]=(byte)0xef;proposed[1]=(byte)0xbb;proposed[2]=(byte)0xbf;System.arraycopy(body,0,proposed,3,body.length);}else proposed=body;if(proposed.length>MigrationApplyPlan.MAX_FILE_BYTES)throw fail(PreparationStatus.APPLY_LIMIT_EXCEEDED,"proposed file:"+logical);return new BuiltFile(original,proposed,originalDigest,MigrationSourceTransactionWriter.sha(proposed),ranges,pres.stream().distinct().sorted().toList(),proposals.stream().distinct().sorted().toList(),metadata(file));}
    private static MethodCallExpr exactCall(CompilationUnit unit,String source,int start,int end){return unit.findAll(MethodCallExpr.class).stream().filter(n->n.getRange().isPresent()).filter(n->{var r=n.getRange().orElseThrow();return offset(source,r.begin)==start&&Math.min(source.length(),offset(source,r.end)+1)==end;}).findFirst().orElseThrow(()->fail(PreparationStatus.STALE_PRECONDITION,"exact AST node missing"));}
    private static int offset(String s,com.github.javaparser.Position p){int line=1,i=0;while(line<p.line&&i<s.length()){char c=s.charAt(i++);if(c=='\r'){if(i<s.length()&&s.charAt(i)=='\n')i++;line++;}else if(c=='\n')line++;}return Math.min(s.length(),i+p.column-1);}
    private static String semantic(MethodCallExpr call){if(call.getArguments().size()!=1||!(call.getArgument(0)instanceof StringLiteralExpr lit))throw fail(PreparationStatus.STALE_PRECONDITION,"locator semantic unavailable");String strategy=switch(call.getNameAsString()){case"id"->"id";case"cssSelector"->"css selector";case"name"->"name";case"className"->"class name";case"tagName"->"tag name";case"linkText"->"link text";case"partialLinkText"->"partial link text";case"xpath"->"xpath";default->throw fail(PreparationStatus.STALE_PRECONDITION,"unsupported By factory");};return"locator-semantic-v1:sha256:"+MigrationDigests.digest("locator-semantic-v1",strategy,lit.asString());}
    private static CompilationUnit parse(String source){var r=new JavaParser(new ParserConfiguration().setLanguageLevel(ParserConfiguration.LanguageLevel.JAVA_17)).parse(source);if(!r.isSuccessful()||r.getResult().isEmpty())throw fail(PreparationStatus.STALE_PRECONDITION,"source parse failed");return r.getResult().orElseThrow();}
    private static String decode(byte[]b,int offset){try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b,offset,b.length-offset)).toString();}catch(CharacterCodingException e){throw fail(PreparationStatus.STALE_PRECONDITION,"invalid UTF-8");}}
    private static MigrationSourcePrecondition.Newline newline(String s){boolean lf=false,crlf=false;for(int i=0;i<s.length();i++)if(s.charAt(i)=='\n'){if(i>0&&s.charAt(i-1)=='\r')crlf=true;else lf=true;}if(lf&&crlf)throw fail(PreparationStatus.STALE_PRECONDITION,"mixed newlines");return crlf?MigrationSourcePrecondition.Newline.CRLF:MigrationSourcePrecondition.Newline.LF;}
    private static MigrationApplyPlan.Metadata metadata(Path file)throws IOException{boolean readOnly=false;var dos=Files.getFileAttributeView(file,java.nio.file.attribute.DosFileAttributeView.class,LinkOption.NOFOLLOW_LINKS);if(dos!=null)readOnly=dos.readAttributes().isReadOnly();List<String>posix=List.of();var pv=Files.getFileAttributeView(file,java.nio.file.attribute.PosixFileAttributeView.class,LinkOption.NOFOLLOW_LINKS);if(pv!=null)posix=pv.readAttributes().permissions().stream().map(Enum::name).sorted().toList();if(readOnly)throw fail(PreparationStatus.READ_ONLY_SOURCE,file.toString());return new MigrationApplyPlan.Metadata(readOnly,posix);}
    private static String verificationDigest(List<MigrationProposal>p){List<String>f=new ArrayList<>();p.stream().flatMap(x->x.requiredVerification().stream()).map(x->x.kind().name()+"|"+x.sideEffect().name()+"|"+(x.subjectRef()==null?"":x.subjectRef())).distinct().sorted().forEach(f::add);return"migration-verification-requirements-v1:sha256:"+MigrationDigests.digest("migration-verification-requirements-v1",f.toArray(String[]::new));}
    private static String exactDiff(String path,byte[]a,byte[]b){String left=new String(a,hasBom(a)?3:0,a.length-(hasBom(a)?3:0),StandardCharsets.UTF_8),right=new String(b,hasBom(b)?3:0,b.length-(hasBom(b)?3:0),StandardCharsets.UTF_8);List<String>x=List.of(left.split("\\R",-1)),y=List.of(right.split("\\R",-1));StringBuilder d=new StringBuilder("--- a/").append(path).append('\n').append("+++ b/").append(path).append('\n').append("@@ -1,").append(x.size()).append(" +1,").append(y.size()).append(" @@\n");x.forEach(v->d.append('-').append(v).append('\n'));y.forEach(v->d.append('+').append(v).append('\n'));return d.toString();}
    private static boolean hasBom(byte[]b){return b.length>=3&&(b[0]&255)==0xef&&(b[1]&255)==0xbb&&(b[2]&255)==0xbf;}
    private void persist(MigrationStateStore store,String ref,byte[]bytes,String kind)throws IOException{faults.beforeArtifact(kind,ref);Path p=store.writeArtifact(ref,bytes);byte[]read=Files.readAllBytes(p);if(!java.util.Arrays.equals(bytes,read))throw new IOException("artifact verification failed");}
    private static void verifyArtifact(MigrationStateStore store,MigrationApplyPlan.SourceArtifact a)throws IOException{byte[]b=read(store,a.logicalRef(),MigrationApplyPlan.MAX_FILE_BYTES);if(b.length!=a.byteCount()||!MigrationSourceTransactionWriter.sha(b).equals(a.sha256()))throw new IOException("source artifact corrupt");}
    private static void verifyDiffArtifact(MigrationStateStore store,MigrationApplyPlan plan)throws IOException{byte[]b=read(store,plan.finalDiffRef(),MigrationApplyPlan.MAX_DIFF_BYTES);if(b.length!=plan.finalDiffBytes()||!MigrationSourceTransactionWriter.sha(b).equals(plan.finalDiffDigest()))throw new IOException("final diff artifact corrupt");}
    private static byte[]read(MigrationStateStore store,String logical,long max)throws IOException{String safe=MigrationRunPlan.logical(logical);Path root=store.root().toAbsolutePath().normalize().toRealPath(),p=root.resolve(safe.replace('/',java.io.File.separatorChar)).normalize();if(!p.startsWith(root)||Files.isSymbolicLink(p)||!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||!p.toRealPath().startsWith(root))throw new IOException("unsafe/missing state artifact");long size=Files.size(p);if(size>max)throw new IOException("artifact limit");return Files.readAllBytes(p);}
    private static Path source(Path root,String logical)throws IOException{String safe=MigrationRunPlan.logical(logical);Path p=root.resolve(safe.replace('/',java.io.File.separatorChar)).normalize();if(!p.startsWith(root)||p.startsWith(root.resolve(".git"))||Files.isSymbolicLink(p))throw new IOException("unsafe source path");return p;}
    private static String digestTarget(Path root,String logical)throws IOException{Path p=source(root,logical);return Files.exists(p,LinkOption.NOFOLLOW_LINKS)&&Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)?MigrationSourceTransactionWriter.sha(Files.readAllBytes(p)):null;}
    private static boolean binding(MigrationGitService.Result r,MigrationApplyPlan p){return r.localContext()!=null&&p.repositoryBindingRef().equals(r.preflight().repositoryBindingRef())&&p.worktreeBindingRef().equals(r.preflight().worktreeBindingRef());}
    private static String sourceRef(String kind,String digest){return"apply/"+kind+"/"+digest.replace(':','-')+".bin";}private static String planRef(String id){return"apply/plans/"+id.replace(':','-')+".json";}private static String registryRef(String tx){return"apply/transactions/"+tx.replace(':','-')+"/ownership.json";}private static String diffRef(String id){return"apply/diffs/"+id.replace(':','-')+".patch";}
    private static MigrationApplyTransaction.OwnershipRegistry registry(String tx,MigrationApplyPlan plan){return MigrationApplyTransaction.OwnershipRegistry.create(tx,plan.applyPlanId(),plan.filePlans().stream().map(f->new MigrationApplyTransaction.OwnershipFile(f.logicalPath(),f.originalSha256(),f.proposedSha256(),f.originalArtifact().logicalRef(),f.proposedArtifact().logicalRef(),f.proposalIds(),f.approvedRanges(),f.metadata())).toList());}
    private static boolean transactionArtifactsMatch(String transactionId,MigrationApplyTransaction.OwnershipRegistry registry,MigrationApplyPlan plan){return transactionId.equals(MigrationApplyTransaction.id(plan))&&registry.equals(registry(transactionId,plan));}
    private static MigrationCheckpoint readCheckpoint(MigrationStateStore store,String id)throws IOException{Path dir=store.root().resolve("checkpoints"),file=dir.resolve(id.replace(':','-')+".json");return new MigrationCheckpointJson().read(read(store,store.root().relativize(file).toString().replace('\\','/'),16*1024*1024));}
    private static MigrationApplyResult result(MigrationApplyPlan p,String tx,MigrationApplyResult.Status status,
            List<MigrationApplyResult.FileResult>files,String before,String after,boolean rollback,String diff,
            List<String>issues){return result(p,tx,status,files,before,after,rollback,diff,null,issues);}
    private static MigrationApplyResult result(MigrationApplyPlan p,String tx,MigrationApplyResult.Status status,
            List<MigrationApplyResult.FileResult>files,String before,String after,boolean rollback,String diff,
            String journalHead,List<String>issues){
        String ref=diff==null?null:p.finalDiffRef();String digest=diff==null?null:p.finalDiffDigest();
        return new MigrationApplyResult(p.applyPlanId(),tx,status,files,before,after,rollback,ref,digest,journalHead,issues);
    }
    private ApplyLock lock(MigrationStateStore store,String repository)throws IOException{Path dir=store.root().resolve("apply/locks");Files.createDirectories(dir);if(Files.isSymbolicLink(dir))throw new IOException("unsafe lock directory");Path path=dir.resolve(repository.substring(repository.lastIndexOf(':')+1)+".lock");FileChannel channel=FileChannel.open(path,StandardOpenOption.CREATE,StandardOpenOption.WRITE);try{FileLock lock=channel.tryLock();if(lock==null){channel.close();return null;}return new ApplyLock(channel,lock);}catch(OverlappingFileLockException e){channel.close();return null;}}
    private record ApplyLock(FileChannel channel,FileLock lock)implements AutoCloseable{public void close()throws IOException{try{lock.release();}finally{channel.close();}}}
    private static final class Journal{private final MigrationStateStore store;private final String tx;private final MigrationApplyCodec codec;private final Faults faults;private final List<MigrationApplyTransaction.Event>events;Journal(MigrationStateStore store,String tx,MigrationApplyCodec codec,Faults faults)throws IOException{this.store=store;this.tx=tx;this.codec=codec;this.faults=faults;this.events=load();verify();}List<MigrationApplyTransaction.Event>events(){return List.copyOf(events);}String head(){return events.isEmpty()?null:events.get(events.size()-1).eventDigest();}void add(MigrationApplyTransaction.EventType type,String path,String observed,String issue)throws IOException{long seq=events.size();faults.beforeJournal(type,seq);var event=MigrationApplyTransaction.Event.create(head(),tx,seq,type,path,observed,issue);String ref=base()+String.format("%08d-%s.json",seq,event.eventDigest().substring(event.eventDigest().lastIndexOf(':')+1, event.eventDigest().lastIndexOf(':')+17));store.writeArtifact(ref,codec.write(event));events.add(event);}void verify(){String previous=null;long sequence=0;for(var e:events){if(e.sequence()!=sequence++||!Objects.equals(previous,e.previousEventDigest())||!e.transactionId().equals(tx))throw new IllegalArgumentException("journal chain");previous=e.eventDigest();}}private List<MigrationApplyTransaction.Event>load()throws IOException{Path dir=store.root().resolve(base().replace('/',java.io.File.separatorChar));if(!Files.exists(dir))return new ArrayList<>();if(Files.isSymbolicLink(dir))throw new IOException("unsafe journal");try(var s=Files.list(dir)){List<Path>paths=s.filter(p->p.getFileName().toString().endsWith(".json")).sorted().toList();List<MigrationApplyTransaction.Event>out=new ArrayList<>();for(Path p:paths)out.add(codec.readEvent(Files.readAllBytes(p)));return out;}}private String base(){return"apply/transactions/"+tx.replace(':','-')+"/events/";}}
    public enum PreparationStatus{PREPARED,PROPOSAL_NOT_FOUND,DECISION_INVALID,DECISION_AMBIGUOUS,DEPENDENCY_UNSATISFIED,CONFLICTING_PROPOSAL,NOT_APPLYABLE_SOURCE_PROPOSAL,NO_SOURCE_CHANGE,STALE_PRECONDITION,READ_ONLY_SOURCE,APPLY_LIMIT_EXCEEDED,ARTIFACT_INTEGRITY_FAILED}
    public record PreparationInput(Path projectRoot,MigrationProposalSet proposalSet,MigrationDecisionLedger decisionLedger,List<String>selectedProposalIds,List<MigrationDependencyResolution>dependencyResolutions,MigrationCheckpoint proposalCheckpoint,List<MigrationEvidenceRef>currentEvidence,MigrationStateStore store){public PreparationInput{Objects.requireNonNull(projectRoot);Objects.requireNonNull(proposalSet);Objects.requireNonNull(decisionLedger);selectedProposalIds=selectedProposalIds==null?List.of():List.copyOf(selectedProposalIds);dependencyResolutions=dependencyResolutions==null?List.of():List.copyOf(dependencyResolutions);Objects.requireNonNull(proposalCheckpoint);currentEvidence=currentEvidence==null?List.of():List.copyOf(currentEvidence);Objects.requireNonNull(store);}}
    public record PreparationResult(PreparationStatus status,MigrationApplyPlan plan,List<String>issues){public PreparationResult{issues=issues==null?List.of():List.copyOf(issues);}}
    public record DryRunSummary(String applyPlanId,List<String>proposalIds,List<FileSummary>files,int editCount,long backupBytes,long targetBytes,List<String>requiredCapabilities,String verificationRequirementsDigest,List<String>limitations){public static DryRunSummary from(MigrationApplyPlan p){return new DryRunSummary(p.applyPlanId(),p.selectedProposalIds(),p.filePlans().stream().map(f->new FileSummary(f.logicalPath(),f.originalSha256(),f.proposedSha256(),f.approvedRanges().size(),f.originalArtifact().byteCount(),f.proposedArtifact().byteCount())).toList(),p.filePlans().stream().mapToInt(f->f.approvedRanges().size()).sum(),p.backupBytes(),p.targetBytes(),p.requiredCapabilities(),p.verificationRequirementsDigest(),p.limitations());}}
    public record FileSummary(String logicalPath,String originalDigest,String proposedDigest,int editCount,long originalBytes,long proposedBytes){}
    public record TempCleanupResult(String transactionId,List<String>removedLogicalPaths,List<String>preservedLogicalPaths){public TempCleanupResult{removedLogicalPaths=List.copyOf(removedLogicalPaths);preservedLogicalPaths=List.copyOf(preservedLogicalPaths);}}
    private record EditBinding(MigrationProposal proposal,MigrationSourcePrecondition pre,MigrationSourceEdit edit){}
    private record BuiltFile(byte[]original,byte[]proposed,String originalDigest,String proposedDigest,List<MigrationApplyPlan.ApprovedRange>ranges,List<String>preconditionDigests,List<String>proposalIds,MigrationApplyPlan.Metadata metadata){}
    private static final class PrepareFailure extends RuntimeException{final PreparationStatus status;final List<String>issues;PrepareFailure(PreparationStatus s,String...i){super(String.join(",",i));status=s;issues=List.of(i);}}
    private static PrepareFailure fail(PreparationStatus status,String...issues){return new PrepareFailure(status,issues);}
}
